bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true
docker exec -i "$cid" node --input-type=module <<'NODE'
import pg from 'pg';
import {readFileSync} from 'node:fs';
const e=process.env;
const p=e.VIDEOBOT_DB_PASSWORD_FILE;
const u=e.VIDEOBOT_DATABASE_URL_FILE?readFileSync(e.VIDEOBOT_DATABASE_URL_FILE,'utf8').trim(): 'postgresql://'+encodeURIComponent(e.VIDEOBOT_DB_USER)+':'+encodeURIComponent(readFileSync(p,'utf8').trim())+'@'+e.VIDEOBOT_DB_HOST+':5432/'+e.VIDEOBOT_DB_NAME;
const c=new pg.Client({connectionString:u,connectionTimeoutMillis:5000});
try{
 await c.connect();
 const t=await c.query("select table_name from information_schema.tables where table_schema='public' and (table_name like '%listing%' or table_name like '%receipt%' or table_name like '%topic%') order by table_name");
 for(const row of t.rows)console.log('TABLE='+row.table_name);
 const q=await c.query("select table_name,column_name from information_schema.columns where table_schema='public' and (table_name like '%listing%' or table_name like '%receipt%' or table_name like '%topic%') order by table_name,ordinal_position");
 for(const table of [...new Set(q.rows.map(x=>x.table_name))])console.log('COL='+table+':'+q.rows.filter(x=>x.table_name===table).map(x=>x.column_name).join(','));
 console.log('VIDEO_THREAD_CONFIG='+Boolean(e.VIDEOBOT_VIDEO_SALE_THREAD_ID));
 console.log('VIDEO_TITLE_CONFIG='+Boolean(e.VIDEOBOT_VIDEO_SALE_TOPIC_TITLE));
}finally{await c.end().catch(()=>{})}
NODE
